property.value:
let $steps := ('map', 'filter', 'peek', 'distinct', 'sorted', 'flatMap', 'mapToObj', 'mapToInt', 'mapToLong',
               'mapToDouble', 'boxed', 'skip', 'dropWhile', 'parallel', 'sequential', 'unordered', 'onClose'),
    $collectors := ('toList', 'toUnmodifiableList', 'toSet', 'toUnmodifiableSet', 'toMap', 'toUnmodifiableMap',
                    'toConcurrentMap', 'groupingBy', 'groupingByConcurrent', 'partitioningBy', 'toCollection'),
    $queried := function($node) {
      exists($node[self::MethodCall][pmd-java:typeIs('java.util.stream.Stream')]
        [*[1][pmd-java:typeIs('org.springframework.data.repository.Repository')]
         or @MethodName = 'getResultStream' and *[1][pmd-java:typeIs('jakarta.persistence.Query')
                                                    or pmd-java:typeIs('javax.persistence.Query')]
         or @MethodName = 'queryForStream' and *[1][pmd-java:typeIs('org.springframework.jdbc.core.JdbcOperations')
           or pmd-java:typeIs('org.springframework.jdbc.core.namedparam.NamedParameterJdbcOperations')]
         or @MethodName = 'stream' and *[1][pmd-java:typeIs('org.hibernate.query.SelectionQuery')]])
    },
    $held := function($node) {
      some $access in $node[self::VariableAccess] satisfies
        (let $name := $access/@Name
         return exists($access/ancestor::*[self::Block or self::TryStatement]
           /(LocalVariableDeclaration/VariableDeclarator | ResourceList/Resource/LocalVariableDeclaration/VariableDeclarator)
           [VariableId/@Name = $name][$queried(*[2])]))
    },
    $fromQuery := function($sink) {
      some $root in $sink/*[1]/descendant-or-self::*[$queried(.) or $held(.)] satisfies
        (every $step in ($root/ancestor-or-self::* intersect $sink/descendant::*) satisfies
          ($step is $step/../*[1] and ($step is $root or exists($step[self::MethodCall][@MethodName = $steps]))))
    },
    $appends := function($argument) {
      exists($argument[self::MethodReference[@MethodName = 'add'][*[1][self::VariableAccess]]
        | self::LambdaExpression[*[2][self::MethodCall[@MethodName = 'add'][*[1][self::VariableAccess]]]]])
    }
return (
  //MethodCall[@MethodName = 'toList' and ArgumentList/@Size = 0 or @MethodName = 'toArray']
  | //MethodCall[@MethodName = 'collect'][ArgumentList[@Size = 3 or *[1][self::MethodCall[@MethodName = $collectors]]]]
  | //MethodCall[@MethodName = ('forEach', 'forEachOrdered')][ArgumentList[@Size = 1][$appends(*[1])]]
)[$fromQuery(.)]
